"""Freeze only candidate LMDB production bytes; preserve all 126 other measured artifacts."""
import argparse
import difflib
import json
import os
from pathlib import Path
import shutil
import time

import sys
sys.path.insert(0, str(Path(__file__).resolve().parent))

from runtime_identity import (HERE, ROOT, ORIGINAL_CP, ORIGINAL_SOURCE, ORIGINAL_SOURCES,
                              canonical_sha, classpath_manifest, delta, original_identity,
                              role, sha, source_hashes, tree_digest, tree_files, write_new)


HERE = Path(__file__).resolve().parent

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--name', required=True, choices=['compact-page'])
    parser.add_argument('--classes', type=Path, default=ROOT / 'core/sail/lmdb/target/classes')
    parser.add_argument('--allow-production-path', action='append', required=True,
                        help='Exact source/resource path relative to repo; repeat for every permitted production delta')
    parser.add_argument('--validation-record', type=Path, action='append', required=True)
    parser.add_argument('--preimages', type=Path, default=HERE / 'baseline/preimages')
    parser.add_argument('--output', type=Path)
    args = parser.parse_args()
    destination = (args.output or HERE / 'runtimes' / args.name).resolve()
    if destination.exists():
        raise SystemExit(f'Refusing stale or existing snapshot: {destination}')
    classpath, original = original_identity()
    before_sources = source_hashes()
    benchmark_sources = json.loads(ORIGINAL_SOURCES.read_text())
    source_delta = delta(benchmark_sources, before_sources)
    role_deltas = {kind: {change: [p for p in paths if role(p) == kind]
                         for change, paths in source_delta.items()}
                   for kind in ['production', 'test', 'original_benchmark_driver']}
    production_paths = set(sum(role_deltas['production'].values(), []))
    if not production_paths or production_paths != set(args.allow_production_path):
        raise ValueError(f'Actual production paths must exactly equal the declared set: {sorted(production_paths)}')
    if role_deltas['production']['added'] or role_deltas['production']['removed']:
        raise ValueError('This narrow candidate freeze does not permit added/removed production sources')
    if any(role_deltas['original_benchmark_driver'].values()):
        raise ValueError('An original benchmark driver changed')
    for path in production_paths:
        preimage = args.preimages / path
        if not preimage.is_file() or sha(preimage) != benchmark_sources[path]:
            raise ValueError(f'Missing exact measured production preimage: {preimage}')
    validation = []
    for path in args.validation_record:
        path = path.resolve(strict=True)
        results = json.loads(path.read_text())
        if (path.name != 'results.json' or not isinstance(results.get('tests'), int) or results['tests'] <= 0
                or results.get('failures') != 0 or results.get('errors') != 0):
            raise ValueError(f'Validation record does not contain a nonzero passing test run: {path}')
        tested_source_file = path.with_name('sources-after.json')
        tested_sources = json.loads(tested_source_file.read_text())
        module_sources = {p:h for p,h in before_sources.items() if p.startswith('core/sail/lmdb/src/')}
        if tested_sources != module_sources:
            raise ValueError(f'Current module sources differ from the successful validation: {tested_source_file}')
        validation.append({'path': str(path), 'sha256': sha(path), 'results': results,
                           'testedSourceFile': str(tested_source_file), 'testedSourceSha256': sha(tested_source_file)})
    original_classes = Path(original[1]['path'])
    old_files = tree_files(original_classes)
    candidate_files = tree_files(args.classes.resolve(strict=True))
    byte_delta = delta(old_files, candidate_files)
    if not byte_delta['changed'] and not byte_delta['added'] and not byte_delta['removed']:
        raise ValueError('Candidate source changed but production bytecode did not')
    def permitted(name):
        for path in production_paths:
            if '/src/main/java/' in path:
                relative = path.split('/src/main/java/', 1)[1]
                stem = relative.removesuffix('.java')
                if name == stem + '.class' or name.startswith(stem + '$') and name.endswith('.class'):
                    return True
                if (stem == 'org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer'
                        and name == 'org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializerPlan.class'):
                    return True
            elif '/src/main/resources/' in path and name == path.split('/src/main/resources/', 1)[1]:
                return True
        return False
    unexpected_classes = [name for names in byte_delta.values() for name in names if not permitted(name)]
    if unexpected_classes:
        raise ValueError(f'Unexpected production class/resource changes: {unexpected_classes}')
    incremental = None
    destination.mkdir(parents=True)
    classes = destination / 'artifacts/001-classes'
    classes.parent.mkdir()
    shutil.copytree(args.classes, classes)
    frozen_files = tree_files(classes)
    if frozen_files != candidate_files or tree_files(args.classes) != candidate_files or source_hashes() != before_sources:
        raise ValueError('Source or compiled bytes changed while freezing; preserve blocked snapshot and investigate')
    parts = classpath.split(os.pathsep)
    parts[1] = str(classes)
    frozen_classpath = os.pathsep.join(parts)
    frozen_manifest = classpath_manifest(frozen_classpath)
    if any(frozen_manifest[i] != original[i] for i in range(127) if i != 1):
        raise ValueError('An artifact other than LMDB production classes changed')
    (destination / 'classpath.txt').write_text(frozen_classpath + '\n')
    write_new(destination / 'classpath-manifest.json', frozen_manifest)
    write_new(destination / 'production-class-files.json', frozen_files)
    write_new(destination / 'source-hashes.json', before_sources)
    write_new(destination / 'baseline-to-candidate-class-delta.json', byte_delta)
    if incremental is not None:
        write_new(destination / 'candidate1-to-candidate2-delta.json', incremental)
    for index, record in enumerate(validation):
        target = destination / 'validation' / str(index)
        target.mkdir(parents=True)
        shutil.copyfile(record['path'], target / 'results.json')
        shutil.copyfile(record['testedSourceFile'], target / 'sources-after.json')
    source_identity = '15fe7d5011+followup-source-map-sha256-' + canonical_sha(before_sources)
    (destination / 'source-identity.txt').write_text(source_identity + '\n')
    patch = []
    for path in sorted(production_paths):
        old = (args.preimages / path).read_text().splitlines(keepends=True)
        new = (ROOT / path).read_text().splitlines(keepends=True)
        patch.extend(difflib.unified_diff(old, new, fromfile='a/' + path, tofile='b/' + path))
        source_copy = destination / 'modified-sources' / path
        source_copy.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(ROOT / path, source_copy)
    (destination / 'production-delta.patch').write_text(''.join(patch))
    mapping = [{'originalAbsolutePath': item['path'],
                'archiveRelativePath': 'rdf4j/' + Path(item['path']).relative_to(ROOT).as_posix(),
                'classpathIndex': i, 'sha256': item['sha256']}
               for i,item in enumerate(frozen_manifest)]
    write_new(destination / 'archive-path-mapping.json', mapping)
    provenance = {
        'format': 1, 'name': args.name, 'createdEpochNs': time.time_ns(),
        'sourceIdentity': source_identity, 'sourceIdentityAlgorithm': 'SHA-256 of full source-hash map serialized as sorted compact JSON',
        'originalMeasuredSourceIdentity': ORIGINAL_SOURCE, 'originalSourceMapFile': str(ORIGINAL_SOURCES),
        'originalSourceMapSha256': sha(ORIGINAL_SOURCES),
        'originalClasspathFile': str(ORIGINAL_CP), 'classpathEntryCount': 127, 'replacedIndex': 1,
        'unchangedOtherEntries': 126, 'exactOriginalHarnessFixtureDiagnosticsLauncher': True,
        'sourceRoleDeltaVersusMeasured': role_deltas,
        'testSourceScope': 'The enumerated test source deltas include prior delivery fixture corrections and new characterization tests; benchmark runtime still uses the exact original frozen test-classes tree.',
        'productionClassDelta': byte_delta,
        'originalProductionTreeSha256': original[1]['sha256'],
        'candidateProductionTreeSha256': tree_digest(frozen_files),
        'validationRecords': validation,
        'currentSourcesEqualEverySuccessfulValidation': True,
        'incrementalCandidateRelationship': incremental,
        'freezeHelperSha256': sha(Path(__file__)), 'identityHelperSha256': sha(HERE / 'runtime_identity.py'),
        'frozenClasspathManifestSha256': sha(destination / 'classpath-manifest.json'),
        'sourceHashManifestSha256': sha(destination / 'source-hashes.json'),
        'productionPatchSha256': sha(destination / 'production-delta.patch'),
        'sourceAndBytecodeStableDuringCopy': True}
    write_new(destination / 'source-provenance.json', provenance)
    descriptor = {'sourceIdentity': source_identity, 'classpathFile': str(destination / 'classpath.txt'),
                  'originalSourceManifestFile': str(ORIGINAL_SOURCES),
                  'originalSourceManifestSha256': sha(ORIGINAL_SOURCES),
                  'classpathFileSha256': sha(destination / 'classpath.txt'),
                  'classpathManifestFile': str(destination / 'classpath-manifest.json'),
                  'classpathManifestSha256': sha(destination / 'classpath-manifest.json'),
                  'sourceManifestFile': str(destination / 'source-hashes.json'),
                  'sourceManifestSha256': sha(destination / 'source-hashes.json'),
                  'provenanceFile': str(destination / 'source-provenance.json'),
                  'provenanceSha256': sha(destination / 'source-provenance.json'),
                  'productionPatchFile': str(destination / 'production-delta.patch'),
                  'productionPatchSha256': sha(destination / 'production-delta.patch')}
    write_new(destination / 'runtime-descriptor.json', descriptor)
    print(json.dumps({'snapshot': str(destination), 'productionTreeSha256': tree_digest(frozen_files),
                      'changedClasses': len(byte_delta['changed']), 'sourceIdentity': source_identity}))


if __name__ == '__main__':
    main()
